import{_ as e,c as t,o,a2 as a}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"make:horizon:supervisor","description":"","frontmatter":{"sidebarPos":14,"sidebarTitle":"make:horizon:supervisor"},"headers":[],"relativePath":"guide/console/make/horizon-supervisor.md","filePath":"guide/console/make/horizon-supervisor.md","lastUpdated":1782594725000}'),s={name:"guide/console/make/horizon-supervisor.md"},r=a(`<h1 id="make-horizon-supervisor" tabindex="-1">make:horizon:supervisor <a class="header-anchor" href="#make-horizon-supervisor" aria-label="Permalink to &quot;make:horizon:supervisor&quot;">​</a></h1><blockquote><p>Generate a Supervisor configuration file for Laravel Horizon</p></blockquote><p><strong>Signature</strong>: <code>modularous:make:horizon:supervisor</code></p><p><strong>Alias</strong>: <code>modularous:create:horizon:supervisor</code></p><p><strong>Category</strong>: Make</p><hr><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>Interactive wizard that creates a Supervisor <code>.conf</code> file for running Laravel Horizon as a daemon. Automatically detects the OS (macOS or Linux), locates a writable Supervisor config directory, and checks for existing processes with the same app name before writing. Prints the <code>supervisorctl</code> commands needed to activate the new config.</p><hr><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>modularous:make:horizon:supervisor</span></span></code></pre></div><p>No arguments or options — fully interactive.</p><hr><h2 id="interactive-prompts" tabindex="-1">Interactive prompts <a class="header-anchor" href="#interactive-prompts" aria-label="Permalink to &quot;Interactive prompts&quot;">​</a></h2><table><thead><tr><th>Prompt</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Config name</td><td><code>b2press-app</code></td><td>Used as the supervisor program name prefix</td></tr><tr><td>PHP binary</td><td><code>php</code></td><td>Path to the PHP executable</td></tr><tr><td>App path</td><td><code>base_path()</code></td><td>Absolute path to your Laravel application</td></tr><tr><td>Command</td><td><code>artisan horizon</code></td><td>Artisan command to run (prepended with app path)</td></tr><tr><td>User</td><td><code>root</code></td><td>OS user to run the process as</td></tr><tr><td>Log file name</td><td><code>horizon</code></td><td>Base name for the log file</td></tr></tbody></table><hr><h2 id="after-running" tabindex="-1">After running <a class="header-anchor" href="#after-running" aria-label="Permalink to &quot;After running&quot;">​</a></h2><p>The command prints the three activation commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> supervisorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reread</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> supervisorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> supervisorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {programName}</span></span></code></pre></div><hr><h2 id="supervisor-config-directories-checked" tabindex="-1">Supervisor config directories checked <a class="header-anchor" href="#supervisor-config-directories-checked" aria-label="Permalink to &quot;Supervisor config directories checked&quot;">​</a></h2><p><strong>macOS</strong> (Homebrew):</p><ul><li><code>/usr/local/etc/supervisor/conf.d</code></li><li><code>/usr/local/etc/supervisor.d</code></li><li><code>/opt/homebrew/etc/supervisor.d</code></li></ul><p><strong>Linux</strong>:</p><ul><li><code>/etc/supervisor/conf.d</code></li><li><code>/etc/supervisord.d</code></li><li><code>/etc/supervisord/conf.d</code></li></ul><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The command will suggest install instructions if Supervisor is not found (<code>brew install supervisor</code> or <code>apt-get install supervisor</code>).</li><li>Not supported on Windows.</li><li>The generated program name is unique (<code>{appName}-{uniqid()}-horizon</code>) to avoid conflicts.</li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/console/make/overview">System Reference</a></li></ul>`,31),i=[r];function n(d,c,l,p,h,u){return o(),t("div",null,i)}const k=e(s,[["render",n]]);export{g as __pageData,k as default};
